128		// 终止前最后一纳秒：2026-12-31 23:59:59.999999999 UTC。
129		lastNs := end.Add(-time.Nanosecond)
130		clk.t = lastNs
131		st, err := s.Status("u")
132		if err != nil {
133			t.Fatal(err)
134		}
135		if !st.Subscribed || st.CurrentTerms != wantTerms ||
136			st.ScheduledEnd == nil || !st.ScheduledEnd.Equal(end) {
