170			st, err = s.Status(id)
171			if err != nil {
172				t.Fatal(err)
173			}
174			if st.Subscribed || st.CurrentTerms != (PlanTerms{}) ||
175				st.PendingChange != nil || st.ScheduledEnd != nil {
176				t.Fatalf("status of %s at end instant = %+v, want unsubscribed zero terms no schedule", id, st)
177			}
178		}
179	
180		// 恰在终止瞬间发生的新事件（不晚于提交时刻）：ErrEventBeforeSubscription。
181		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "at-end", At: end, Quantity: 1}); !errors.Is(err, ErrEventBeforeSubscription) {
