114		// 进入二月、一月账期已经结束：首次为一月出账。超额 5×100=500，
115		// 税 (1000+500)×10%=150，应付 1650，截止 2026-02-08 00:00 UTC。
116		clk.t = utc(2026, 2, 1, 0, 0)
117		first, err := s.CreateBill("acct-rebill", jan(2026))
118		if err != nil {
119			t.Fatalf("first bill: %v", err)
120		}
121		wantRebillStatic(t, first)
122		wantRebillPayment(t, first, 0, 1650, false)
123	
124		// 首次登记 400 分付款后再次出账：返回同一张账单，付款状态反映这次
125		// 请求时的真实记录——已付 400、余额 1250、尚未付清；出账时固定的
126		// 部分全部保持首次出账时的内容。
127		p1, err := s.RecordPayment("acct-rebill", "pay-1", jan(2026), 400)
128		if err != nil || !p1.Registered || p1.BillBalance != 1250 || p1.Settled {
129			t.Fatalf("pay-1 400: %+v %v", p1, err)
130		}
131		rebill, err := s.CreateBill("acct-rebill", jan(2026))
132		if err != nil {
133			t.Fatalf("rebill after pay-1: %v", err)
134		}
135		wantRebillStatic(t, rebill)
136		wantRebillPayment(t, rebill, 400, 1250, false)
137		wantJanBillConsistent(t, s, rebill, 400, 1250, false)
138	
139		// 用另一付款标识结清剩余 1250 分，再次出账：已付 1650、余额零、
140		// 已经付清；已经登记的付款继续有效，再次出账不能把账单恢复成
141		// 刚生成时的未付款状态。
142		p2, err := s.RecordPayment("acct-rebill", "pay-2", jan(2026), 1250)
143		if err != nil || !p2.Registered || p2.BillBalance != 0 || !p2.Settled {
144			t.Fatalf("pay-2 1250: %+v %v", p2, err)
145		}
146		rebill, err = s.CreateBill("acct-rebill", jan(2026))
147		if err != nil {
148			t.Fatalf("rebill after pay-2: %v", err)
149		}
150		wantRebillStatic(t, rebill)
151		wantRebillPayment(t, rebill, 1650, 0, true)
152		wantJanBillConsistent(t, s, rebill, 1650, 0, true)
153	
154		// 调用方此前保存的首次出账结果仍保留取得时的状态：已付零、
155		// 余额 1650、未付清；后续付款与再次出账不会把那份已返回的结果
156		// 改成最新状态。
157		wantRebillPayment(t, first, 0, 1650, false)
158	
159		// 结清后以新的付款标识再登记 1 分：按现有超额付款规则拒绝，
160		// 不能产生新的欠款或额外收款。
161		if _, err := s.RecordPayment("acct-rebill", "pay-3", jan(2026), 1); !errors.Is(err, ErrPaymentExceedsBalance) {
162			t.Fatalf("pay-3 1 on settled bill: %v", err)
163		}
164		rebill, err = s.CreateBill("acct-rebill", jan(2026))
165		if err != nil {
166			t.Fatalf("rebill after rejected pay-3: %v", err)
167		}
168		wantRebillStatic(t, rebill)
169		wantRebillPayment(t, rebill, 1650, 0, true)
170		wantJanBillConsistent(t, s, rebill, 1650, 0, true)
171	
172		// 登记按月取消（请求时刻 2026-02-10，终止时刻 2026-03-01 00:00 UTC）。
173		clk.t = utc(2026, 2, 10, 0, 0)
174		cancel, err := s.CancelSubscription("acct-rebill")
175		if err != nil || !cancel.Cancelled || !cancel.Cancellation.EndAt.Equal(utc(2026, 3, 1, 0, 0)) {
176			t.Fatalf("cancel: %+v %v", cancel, err)
177		}
178	
179		// 终止时刻已经到达：订阅已终止，但已生成且付过款的一月账单仍能
180		// 再次出账取得，返回原账单当前付款状态，不要求账户重新开通订阅。
181		clk.t = utc(2026, 3, 1, 0, 0)
182		st, err := s.Status("acct-rebill")
183		if err != nil {
184			t.Fatalf("status after termination: %v", err)
185		}
186		if st.Subscribed {
187			t.Fatalf("subscription must be terminated: %+v", st)
188		}
189		rebill, err = s.CreateBill("acct-rebill", jan(2026))
190		if err != nil {
191			t.Fatalf("rebill after subscription terminated: %v", err)
192		}
193		wantRebillStatic(t, rebill)
194		wantRebillPayment(t, rebill, 1650, 0, true)
195		wantJanBillConsistent(t, s, rebill, 1650, 0, true)
196		// 首次出账结果在取消与终止之后依然保持取得时的未付款状态。
197		wantRebillPayment(t, first, 0, 1650, false)
198	}
