141	// TestCancelInteractsWithPlanChanges 覆盖清除待生效安排、等待期拒绝新安排，
142	// 以及恰在换套餐生效月初时先承认切换、取消从再下一月生效。
143	func TestCancelInteractsWithPlanChanges(t *testing.T) {
144		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
145		mustPlan(t, s, planDef("a", 1000, 10, 5, 0))
146		mustPlan(t, s, planDef("b", 2000, 20, 8, 0))
147		mustAccount(t, s, "u")
148		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
149	
150		// 登记取消清除尚未生效的安排，等待期间拒绝新安排。
151		mustSchedule(t, s, "u", "b")
152		r := mustCancel(t, s, "u")
153		if !r.Cancellation.EndAt.Equal(utc(2026, 2, 1, 0, 0)) {
154			t.Fatalf("end = %v", r.Cancellation.EndAt)
155		}
156		st, _ := s.Status("u")
157		if st.PendingChange != nil {
158			t.Fatalf("pending survived cancel: %+v", st.PendingChange)
159		}
160		if _, err := s.SchedulePlanChange("u", "b"); !errors.Is(err, ErrPlanChangeWhileCancelling) {
161			t.Fatalf("schedule while cancelling: %v", err)
162		}
163		// 失败的安排不留痕迹。
164		st, _ = s.Status("u")
165		if st.PendingChange != nil || st.ScheduledEnd == nil {
166			t.Fatalf("state after rejected schedule: %+v", st)
167		}
168	
169		// 恰在换套餐生效的月初：先承认该次切换，取消从再下一月生效。
170		mustAccount(t, s, "v")
171		mustSubscribe(t, s, "v", "a", utc(2026, 1, 1, 0, 0))
172		mustSchedule(t, s, "v", "b")
173		clk.t = utc(2026, 2, 1, 0, 0)
174		rv := mustCancel(t, s, "v")
175		if !rv.Cancellation.EndAt.Equal(utc(2026, 3, 1, 0, 0)) {
176			t.Fatalf("boundary cancel end = %v, want 2026-03-01", rv.Cancellation.EndAt)
177		}
178		st, _ = s.Status("v")
179		if st.CurrentTerms.PlanID != "b" || st.PendingChange != nil {
180			t.Fatalf("switch not acknowledged before cancel: %+v", st)
181		}
182		// 终止后该段以 b 套餐条件记入历史。
183		clk.t = utc(2026, 3, 1, 0, 0)
184		st, _ = s.Status("v")
185		if st.Subscribed {
186			t.Fatalf("v still subscribed after end")
187		}
188		febBill := mustBill(t, s, "v", feb(2026))
189		if febBill.Terms.PlanID != "b" || febBill.MonthlyFee != 2000 {
190			t.Fatalf("feb bill after boundary cancel: %+v", febBill)
191		}
192	}
