264		if _, err := s.RecordPayment("u", "p", jan(2026), 1000); err != nil {
265			t.Fatal(err)
266		}
267		st, _ = s.Status("u")
268		if st.Suspended || st.Subscribed {
269			t.Fatalf("payment revived subscription: %+v", st)
270		}
271	}
